150	        if (lastName != null) {
151	            owners = this.clinicService.findOwnerByLastName(lastName);
152	        } else {
153	            owners = this.clinicService.findAllOwners();
154	        }
155	        if (owners.isEmpty()) {
156	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
157	        }
158	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
159	    }
