174	        HttpHeaders headers = new HttpHeaders();
175	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
176	        this.registrationDateAssigner.assign(owner);
177	        if (this.cityCapacityChecker.isCityAtCapacity(owner)) {
178	            return new ResponseEntity<>(HttpStatus.CONFLICT);
