181	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
182	        }
183	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
184	        if (sharesHousehold && this.householdDuplicateChecker.isDuplicate(owner)) {
185	            this.householdAssigner.assign(owner);
186	        }
187	        if (this.identityDuplicateChecker.isDuplicate(owner)) {
188	            return new ResponseEntity<>(HttpStatus.CONFLICT);
189	        }
